    { const char * tb_v1313 = "#define TB_WIN_STACK_MSG \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1313; }
    { const char * tb_v1314 = "// переполнение стека — сразу (это никогда не «нормальное» исключение)\n"; *(const char * *)tb_grow(v_lines) = tb_v1314; }
