    { const char * tb_v1462 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1462; }
    { const char * tb_v1463 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v1463; }
    { const char * tb_v1464 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1464; }
    { const char * tb_v1465 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v1465; }
    { const char * tb_v1466 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v1466; }
    { const char * tb_v1467 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v1467; }
    { const char * tb_v1468 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v1468; }
    { const char * tb_v1469 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v1469; }
    { const char * tb_v1470 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v1470; }
    { const char * tb_v1471 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v1471; }
