    { const char * tb_v2740 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2740; }
    { const char * tb_v2741 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2741; }
    { const char * tb_v2742 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2742; }
