    { const char * tb_v2777 = "    d->keys = text ? tb_list_new(sizeof(const char *)) : tb_list_new_np(sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "    d->vals = tb_list_new(vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
    { const char * tb_v2779 = "    d->slots = 0; d->pos = 0; d->npos = 0; d->base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2779; }
