    { const char * tb_v2830 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2830; }
    { const char * tb_v2831 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v2831; }
    { const char * tb_v2832 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2832; }
    { const char * tb_v2833 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2833; }
    { const char * tb_v2834 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2834; }
    { const char * tb_v2835 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2835; }
    { const char * tb_v2836 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v2836; }
    { const char * tb_v2837 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2837; }
    { const char * tb_v2838 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2838; }
    { const char * tb_v2839 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v2839; }
    { const char * tb_v2840 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2840; }
    { const char * tb_v2841 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v2841; }
    { const char * tb_v2842 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2842; }
    { const char * tb_v2843 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2843; }
    { const char * tb_v2844 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2844; }
    { const char * tb_v2845 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2845; }
    { const char * tb_v2846 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2846; }
    { const char * tb_v2847 = "        d->slots[i] = d->keys->len | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2847; }
    { const char * tb_v2848 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2848; }
    { const char * tb_v2849 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v2849; }
    { const char * tb_v2850 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2850; }
    { const char * tb_v2851 = "TB_API void *tb_dget(tb_dict *d, const void *k, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2851; }
    { const char * tb_v2852 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2852; }
    { const char * tb_v2853 = "    if (TB_RARE(at < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2853; }
    { const char * tb_v2854 = "        if (d->text) tb_crash(line, tb_cat(\"в dict нет ключа: \", *(const char * const *)k));\n"; *(const char * *)tb_grow(v_lines) = tb_v2854; }
    { const char * tb_v2855 = "        tb_crash(line, tb_cat(\"в dict нет ключа: \", tb_itos(*(const long long *)k)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2855; }
    { const char * tb_v2856 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2856; }
    { const char * tb_v2857 = "    return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2857; }
    { const char * tb_v2858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2858; }
    { const char * tb_v2859 = "// together: шаг 1 — просим память принести место ключа заранее\n"; *(const char * *)tb_grow(v_lines) = tb_v2859; }
    { const char * tb_v2860 = "TB_INL unsigned long long tb_dpre1(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2860; }
    { const char * tb_v2861 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2861; }
    { const char * tb_v2862 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2862; }
    { const char * tb_v2863 = "        if (at < (unsigned long long)d->vals->len) __builtin_prefetch(d->vals->data + at * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2863; }
    { const char * tb_v2864 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2864; }
    { const char * tb_v2865 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2865; }
    { const char * tb_v2866 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2866; }
    { const char * tb_v2867 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2867; }
    { const char * tb_v2868 = "        if (o < (unsigned long long)d->npos) { __builtin_prefetch(&d->pos[o]); return o; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2868; }
    { const char * tb_v2869 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2869; }
    { const char * tb_v2870 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2870; }
    { const char * tb_v2871 = "    unsigned long long i = tb_hash(d, k) & (d->nslots - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
