    { const char * tb_v2873 = "    return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v2873; }
    { const char * tb_v2874 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2874; }
    { const char * tb_v2875 = "// шаг 2 — место приехало: просим принести ключ и значение\n"; *(const char * *)tb_grow(v_lines) = tb_v2875; }
    { const char * tb_v2876 = "TB_INL void tb_dpre2(tb_dict *d, unsigned long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2876; }
    { const char * tb_v2877 = "    if (i == ~0ULL || d->mode == 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2877; }
    { const char * tb_v2878 = "    long long s = d->mode == 2 ? d->pos[i] : (d->slots[i] & TB_DAT);\n"; *(const char * *)tb_grow(v_lines) = tb_v2878; }
    { const char * tb_v2879 = "    if (s != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2879; }
    { const char * tb_v2880 = "        if (d->mode == 0) __builtin_prefetch(d->keys->data + (s - 1) * d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2880; }
    { const char * tb_v2881 = "        __builtin_prefetch(d->vals->data + (s - 1) * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2881; }
    { const char * tb_v2882 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2882; }
    { const char * tb_v2883 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2883; }
    { const char * tb_v2884 = "// элемент списка заранее (prefetch за пределами списка ничего не ломает)\n"; *(const char * *)tb_grow(v_lines) = tb_v2884; }
    { const char * tb_v2885 = "TB_INL void tb_lpre(tb_list *l, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2885; }
    { const char * tb_v2886 = "    __builtin_prefetch(l->data + i * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2886; }
    { const char * tb_v2887 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2887; }
    { const char * tb_v2888 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2888; }
    { const char * tb_v2889 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2889; }
    { const char * tb_v2890 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2890; }
