    { const char * tb_v2893 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v2893; }
    { const char * tb_v2894 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2894; }
    { const char * tb_v2895 = "TB_API void *tb_cold_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2895; }
    { const char * tb_v2896 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2896; }
    { const char * tb_v2897 = "    void *r = tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2897; }
    { const char * tb_v2898 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2898; }
    { const char * tb_v2899 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v2899; }
    { const char * tb_v2900 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2900; }
    { const char * tb_v2901 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2901; }
    { const char * tb_v2902 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v2902; }
    { const char * tb_v2903 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2903; }
    { const char * tb_v2904 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2904; }
    { const char * tb_v2905 = "    return tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2905; }
    { const char * tb_v2906 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2906; }
    { const char * tb_v2907 = "TB_API void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2907; }
    { const char * tb_v2908 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2908; }
    { const char * tb_v2909 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2909; }
    { const char * tb_v2910 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2910; }
    { const char * tb_v2911 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2911; }
    { const char * tb_v2912 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2912; }
    { const char * tb_v2913 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v2913; }
    { const char * tb_v2914 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2914; }
    { const char * tb_v2915 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2915; }
    { const char * tb_v2916 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2916; }
    { const char * tb_v2917 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2917; }
    { const char * tb_v2918 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2918; }
    { const char * tb_v2919 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2919; }
    { const char * tb_v2920 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2920; }
    { const char * tb_v2921 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v2921; }
    { const char * tb_v2922 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2922; }
    { const char * tb_v2923 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2923; }
    { const char * tb_v2924 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2924; }
    { const char * tb_v2925 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2925; }
    { const char * tb_v2926 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2926; }
    { const char * tb_v2927 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2927; }
    { const char * tb_v2928 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v2928; }
    { const char * tb_v2929 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2929; }
    { const char * tb_v2930 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v2930; }
    { const char * tb_v2931 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2931; }
    { const char * tb_v2932 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2932; }
    { const char * tb_v2933 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2933; }
    { const char * tb_v2934 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2934; }
    { const char * tb_v2935 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v2935; }
    { const char * tb_v2936 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2936; }
    { const char * tb_v2937 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2937; }
    { const char * tb_v2938 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2938; }
    { const char * tb_v2939 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2939; }
    { const char * tb_v2940 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2940; }
    { const char * tb_v2941 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2941; }
    { const char * tb_v2942 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2942; }
    { const char * tb_v2943 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2943; }
    { const char * tb_v2944 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2944; }
    { const char * tb_v2945 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2945; }
    { const char * tb_v2946 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2946; }
    { const char * tb_v2947 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v2947; }
    { const char * tb_v2948 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v2948; }
    { const char * tb_v2949 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v2949; }
    { const char * tb_v2950 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2950; }
    { const char * tb_v2951 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2951; }
    { const char * tb_v2952 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v2952; }
    { const char * tb_v2953 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v2953; }
    { const char * tb_v2954 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2954; }
    { const char * tb_v2955 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2955; }
    { const char * tb_v2956 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2956; }
    { const char * tb_v2957 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2957; }
    { const char * tb_v2958 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2958; }
    { const char * tb_v2959 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2959; }
    { const char * tb_v2960 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2960; }
    { const char * tb_v2961 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2961; }
    { const char * tb_v2962 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2962; }
    { const char * tb_v2963 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2963; }
    { const char * tb_v2964 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2964; }
    { const char * tb_v2965 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2965; }
    { const char * tb_v2966 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2966; }
    { const char * tb_v2967 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2967; }
    { const char * tb_v2968 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2968; }
    { const char * tb_v2969 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2969; }
    { const char * tb_v2970 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2970; }
    { const char * tb_v2971 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2971; }
    { const char * tb_v2972 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2972; }
    { const char * tb_v2973 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2973; }
    { const char * tb_v2974 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2974; }
    { const char * tb_v2975 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2975; }
    { const char * tb_v2976 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2976; }
    { const char * tb_v2977 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2977; }
    { const char * tb_v2978 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2978; }
    { const char * tb_v2979 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v2979; }
    { const char * tb_v2980 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2980; }
    { const char * tb_v2981 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2981; }
    { const char * tb_v2982 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2982; }
    { const char * tb_v2983 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v2983; }
    { const char * tb_v2984 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2984; }
    { const char * tb_v2985 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2985; }
    { const char * tb_v2986 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2986; }
    { const char * tb_v2987 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2987; }
    { const char * tb_v2988 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v2988; }
    { const char * tb_v2989 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v2989; }
    { const char * tb_v2990 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v2990; }
    { const char * tb_v2991 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v2991; }
    { const char * tb_v2992 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2992; }
    { const char * tb_v2993 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2993; }
    { const char * tb_v2994 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2994; }
    { const char * tb_v2995 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2995; }
    { const char * tb_v2996 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2996; }
    { const char * tb_v2997 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2997; }
    { const char * tb_v2998 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v2998; }
    { const char * tb_v2999 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2999; }
    { const char * tb_v3000 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3000; }
    { const char * tb_v3001 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3001; }
    { const char * tb_v3002 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3002; }
    { const char * tb_v3003 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3003; }
    { const char * tb_v3004 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3004; }
    { const char * tb_v3005 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3005; }
    { const char * tb_v3006 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3006; }
    { const char * tb_v3007 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3007; }
    { const char * tb_v3008 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3008; }
    { const char * tb_v3009 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v3009; }
    { const char * tb_v3010 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3010; }
    { const char * tb_v3011 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3011; }
    { const char * tb_v3012 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3012; }
    { const char * tb_v3013 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3013; }
    { const char * tb_v3014 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3014; }
    { const char * tb_v3015 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3015; }
    { const char * tb_v3016 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3016; }
    { const char * tb_v3017 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3017; }
    { const char * tb_v3018 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3018; }
    { const char * tb_v3019 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v3019; }
    { const char * tb_v3020 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3020; }
    { const char * tb_v3021 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v3021; }
    { const char * tb_v3022 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3022; }
    { const char * tb_v3023 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3023; }
    { const char * tb_v3024 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3024; }
    { const char * tb_v3025 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3025; }
    { const char * tb_v3026 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3026; }
    { const char * tb_v3027 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v3027; }
    { const char * tb_v3028 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3028; }
    { const char * tb_v3029 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v3029; }
    { const char * tb_v3030 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3030; }
    { const char * tb_v3031 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3031; }
    { const char * tb_v3032 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3032; }
    { const char * tb_v3033 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3033; }
    { const char * tb_v3034 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3034; }
    { const char * tb_v3035 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3035; }
    { const char * tb_v3036 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3036; }
    { const char * tb_v3037 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3037; }
    { const char * tb_v3038 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3038; }
    { const char * tb_v3039 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3039; }
