    { const char * tb_v3042 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3042; }
    { const char * tb_v3043 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3043; }
    { const char * tb_v3044 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3044; }
    { const char * tb_v3045 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3045; }
    { const char * tb_v3046 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3046; }
    { const char * tb_v3047 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3047; }
    { const char * tb_v3048 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3048; }
    { const char * tb_v3049 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3049; }
