    { const char * tb_v3413 = "        if (x < 0 || (bn < 63 && (x >> bn))) tb_crash(line, \"число не влезает в поле bits: от 0 до 2 в степени N без единицы\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3413; }
    { const char * tb_v3414 = "        uint64_t m = bn < 64 ? (((uint64_t)1 << bn) - 1) << bo : ~(uint64_t)0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3414; }
    { const char * tb_v3415 = "        uint64_t v = tb_shape_raw(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v3415; }
