    { const char * tb_v3733 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3733; }
    { const char * tb_v3734 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3734; }
    { const char * tb_v3735 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3735; }
    { const char * tb_v3736 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3736; }
    { const char * tb_v3737 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3737; }
    { const char * tb_v3738 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v3738; }
