    { const char * tb_v3783 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3783; }
    { const char * tb_v3784 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3784; }
    { const char * tb_v3785 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3785; }
    { const char * tb_v3786 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3786; }
    { const char * tb_v3787 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3787; }
