    { const char * tb_v4310 = "    double lh = size * 5 / 4.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4310; }
    { const char * tb_v4311 = "    return (int)floor(lh * f->asc / (f->asc - f->desc) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4311; }
    { const char * tb_v4312 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4312; }
    { const char * tb_v4313 = "static unsigned tb_utf8_next(const unsigned char **pp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4313; }
    { const char * tb_v4314 = "    const unsigned char *p = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4314; }
    { const char * tb_v4315 = "    unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4315; }
