    { const char * tb_v4317 = "        int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4317; }
    { const char * tb_v4318 = "        u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v4318; }
    { const char * tb_v4319 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v4319; }
    { const char * tb_v4320 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4320; }
    { const char * tb_v4321 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4321; }
    { const char * tb_v4322 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v4322; }
    { const char * tb_v4323 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4323; }
    { const char * tb_v4324 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4324; }
    { const char * tb_v4325 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4325; }
    { const char * tb_v4326 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v4326; }
    { const char * tb_v4327 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4327; }
    { const char * tb_v4328 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4328; }
    { const char * tb_v4329 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4329; }
    { const char * tb_v4330 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4330; }
    { const char * tb_v4331 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4331; }
    { const char * tb_v4332 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v4332; }
    { const char * tb_v4333 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4333; }
    { const char * tb_v4334 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v4334; }
    { const char * tb_v4335 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4335; }
    { const char * tb_v4336 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4336; }
    { const char * tb_v4337 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v4337; }
    { const char * tb_v4338 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4338; }
    { const char * tb_v4339 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4339; }
    { const char * tb_v4340 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v4340; }
    { const char * tb_v4341 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4341; }
    { const char * tb_v4342 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v4342; }
    { const char * tb_v4343 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4343; }
    { const char * tb_v4344 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4344; }
    { const char * tb_v4345 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4345; }
    { const char * tb_v4346 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4346; }
