    { const char * tb_v4352 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v4352; }
    { const char * tb_v4353 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4353; }
    { const char * tb_v4354 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4354; }
    { const char * tb_v4355 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4355; }
    { const char * tb_v4356 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v4356; }
    { const char * tb_v4357 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v4357; }
    { const char * tb_v4358 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v4358; }
    { const char * tb_v4359 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v4359; }
    { const char * tb_v4360 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v4360; }
    { const char * tb_v4361 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4361; }
    { const char * tb_v4362 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v4362; }
    { const char * tb_v4363 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v4363; }
    { const char * tb_v4364 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4364; }
    { const char * tb_v4365 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4365; }
    { const char * tb_v4366 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4366; }
    { const char * tb_v4367 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4367; }
    { const char * tb_v4368 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v4368; }
    { const char * tb_v4369 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4369; }
    { const char * tb_v4370 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4370; }
    { const char * tb_v4371 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4371; }
    { const char * tb_v4372 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v4372; }
    { const char * tb_v4373 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v4373; }
    { const char * tb_v4374 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v4374; }
    { const char * tb_v4375 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4375; }
    { const char * tb_v4376 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v4376; }
    { const char * tb_v4377 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v4377; }
    { const char * tb_v4378 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v4378; }
    { const char * tb_v4379 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v4379; }
    { const char * tb_v4380 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4380; }
    { const char * tb_v4381 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v4381; }
    { const char * tb_v4382 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4382; }
    { const char * tb_v4383 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4383; }
    { const char * tb_v4384 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v4384; }
    { const char * tb_v4385 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v4385; }
    { const char * tb_v4386 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v4386; }
    { const char * tb_v4387 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4387; }
    { const char * tb_v4388 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v4388; }
    { const char * tb_v4389 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v4389; }
    { const char * tb_v4390 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v4390; }
    { const char * tb_v4391 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v4391; }
    { const char * tb_v4392 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4392; }
