    { const char * tb_v4397 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v4397; }
    { const char * tb_v4398 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4398; }
    { const char * tb_v4399 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v4399; }
    { const char * tb_v4400 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v4400; }
    { const char * tb_v4401 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4401; }
    { const char * tb_v4402 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v4402; }
    { const char * tb_v4403 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4403; }
    { const char * tb_v4404 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v4404; }
    { const char * tb_v4405 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v4405; }
    { const char * tb_v4406 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4406; }
    { const char * tb_v4407 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4407; }
    { const char * tb_v4408 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v4408; }
    { const char * tb_v4409 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4409; }
    { const char * tb_v4410 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v4410; }
    { const char * tb_v4411 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4411; }
    { const char * tb_v4412 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4412; }
    { const char * tb_v4413 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4413; }
    { const char * tb_v4414 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v4414; }
    { const char * tb_v4415 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4415; }
