    { const char * tb_v5558 = "TB_API int tb_vk_buffer_m(VkDeviceSize size, VkFlags usage, VkBuffer *buf, void **map, VkDeviceMemory *memo) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5558; }
