    { const char * tb_v6198 = "// ---------- Metal (Mac) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6198; }
    { const char * tb_v6199 = "// Metal зовём так же, как Cocoa: через objc_msgSend. Шейдер (tb_msl выше, compiler/gpu/tb.metal)\n"; *(const char * *)tb_grow(v_lines) = tb_v6199; }
