    { const char * tb_v6846 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6846; }
    { const char * tb_v6847 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v6847; }
    { const char * tb_v6848 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v6848; }
    { const char * tb_v6849 = "    case XK_Down: return TB_K_DOWN; case XK_Left: return TB_K_LEFT; case XK_Right: return TB_K_RIGHT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6849; }
    { const char * tb_v6850 = "    case XK_Shift_L: case XK_Shift_R: return TB_K_SHIFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6850; }
