    { const char * tb_v6957 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6957; }
    { const char * tb_v6958 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v6958; }
    { const char * tb_v6959 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v6959; }
    { const char * tb_v6960 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v6960; }
    { const char * tb_v6961 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v6961; }
    { const char * tb_v6962 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v6962; }
    { const char * tb_v6963 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6963; }
    { const char * tb_v6964 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6964; }
    { const char * tb_v6965 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6965; }
    { const char * tb_v6966 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6966; }
    { const char * tb_v6967 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6967; }
    { const char * tb_v6968 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v6968; }
    { const char * tb_v6969 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6969; }
    { const char * tb_v6970 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v6970; }
    { const char * tb_v6971 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v6971; }
    { const char * tb_v6972 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v6972; }
    { const char * tb_v6973 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6973; }
    { const char * tb_v6974 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6974; }
    { const char * tb_v6975 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v6975; }
    { const char * tb_v6976 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v6976; }
    { const char * tb_v6977 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v6977; }
    { const char * tb_v6978 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6978; }
    { const char * tb_v6979 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6979; }
    { const char * tb_v6980 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6980; }
    { const char * tb_v6981 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6981; }
    { const char * tb_v6982 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6982; }
    { const char * tb_v6983 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6983; }
    { const char * tb_v6984 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6984; }
    { const char * tb_v6985 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6985; }
    { const char * tb_v6986 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6986; }
    { const char * tb_v6987 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6987; }
    { const char * tb_v6988 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6988; }
    { const char * tb_v6989 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6989; }
    { const char * tb_v6990 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6990; }
    { const char * tb_v6991 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6991; }
    { const char * tb_v6992 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6992; }
    { const char * tb_v6993 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v6993; }
    { const char * tb_v6994 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6994; }
    { const char * tb_v6995 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6995; }
    { const char * tb_v6996 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6996; }
