    { const char * tb_v6998 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6998; }
    { const char * tb_v6999 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6999; }
    { const char * tb_v7000 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v7000; }
    { const char * tb_v7001 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7001; }
    { const char * tb_v7002 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7002; }
    { const char * tb_v7003 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v7003; }
