    { const char * tb_v7133 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7133; }
    { const char * tb_v7134 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7134; }
    { const char * tb_v7135 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7135; }
    { const char * tb_v7136 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7136; }
    { const char * tb_v7137 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v7137; }
    { const char * tb_v7138 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7138; }
    { const char * tb_v7139 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7139; }
    { const char * tb_v7140 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v7140; }
    { const char * tb_v7141 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v7141; }
    { const char * tb_v7142 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v7142; }
    { const char * tb_v7143 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v7143; }
    { const char * tb_v7144 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7144; }
    { const char * tb_v7145 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v7145; }
    { const char * tb_v7146 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7146; }
    { const char * tb_v7147 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7147; }
    { const char * tb_v7148 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7148; }
    { const char * tb_v7149 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7149; }
    { const char * tb_v7150 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7150; }
    { const char * tb_v7151 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7151; }
    { const char * tb_v7152 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7152; }
    { const char * tb_v7153 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7153; }
    { const char * tb_v7154 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7154; }
    { const char * tb_v7155 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7155; }
    { const char * tb_v7156 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7156; }
    { const char * tb_v7157 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7157; }
    { const char * tb_v7158 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7158; }
    { const char * tb_v7159 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7159; }
    { const char * tb_v7160 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7160; }
    { const char * tb_v7161 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v7161; }
    { const char * tb_v7162 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v7162; }
    { const char * tb_v7163 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7163; }
    { const char * tb_v7164 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v7164; }
    { const char * tb_v7165 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v7165; }
    { const char * tb_v7166 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7166; }
    { const char * tb_v7167 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7167; }
    { const char * tb_v7168 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v7168; }
    { const char * tb_v7169 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7169; }
    { const char * tb_v7170 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7170; }
    { const char * tb_v7171 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7171; }
    { const char * tb_v7172 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v7172; }
    { const char * tb_v7173 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7173; }
    { const char * tb_v7174 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7174; }
    { const char * tb_v7175 = "    if (gpu) { if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7175; }
    { const char * tb_v7176 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7176; }
    { const char * tb_v7177 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7177; }
    { const char * tb_v7178 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7178; }
    { const char * tb_v7179 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7179; }
    { const char * tb_v7180 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7180; }
    { const char * tb_v7181 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7181; }
    { const char * tb_v7182 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7182; }
    { const char * tb_v7183 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7183; }
    { const char * tb_v7184 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7184; }
    { const char * tb_v7185 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7185; }
    { const char * tb_v7186 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7186; }
    { const char * tb_v7187 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7187; }
    { const char * tb_v7188 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7188; }
    { const char * tb_v7189 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7189; }
    { const char * tb_v7190 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7190; }
    { const char * tb_v7191 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7191; }
    { const char * tb_v7192 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v7192; }
    { const char * tb_v7193 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v7193; }
    { const char * tb_v7194 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7194; }
    { const char * tb_v7195 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7195; }
    { const char * tb_v7196 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7196; }
    { const char * tb_v7197 = "                    tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7197; }
    { const char * tb_v7198 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v7198; }
    { const char * tb_v7199 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7199; }
    { const char * tb_v7200 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7200; }
    { const char * tb_v7201 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7201; }
    { const char * tb_v7202 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v7202; }
    { const char * tb_v7203 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v7203; }
    { const char * tb_v7204 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v7204; }
    { const char * tb_v7205 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v7205; }
    { const char * tb_v7206 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7206; }
    { const char * tb_v7207 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v7207; }
    { const char * tb_v7208 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v7208; }
    { const char * tb_v7209 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v7209; }
    { const char * tb_v7210 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7210; }
    { const char * tb_v7211 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7211; }
    { const char * tb_v7212 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7212; }
    { const char * tb_v7213 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7213; }
    { const char * tb_v7214 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7214; }
    { const char * tb_v7215 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v7215; }
    { const char * tb_v7216 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7216; }
    { const char * tb_v7217 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v7217; }
    { const char * tb_v7218 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7218; }
    { const char * tb_v7219 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7219; }
    { const char * tb_v7220 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7220; }
    { const char * tb_v7221 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7221; }
    { const char * tb_v7222 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v7222; }
    { const char * tb_v7223 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7223; }
    { const char * tb_v7224 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7224; }
    { const char * tb_v7225 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v7225; }
    { const char * tb_v7226 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7226; }
    { const char * tb_v7227 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7227; }
    { const char * tb_v7228 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7228; }
    { const char * tb_v7229 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v7229; }
    { const char * tb_v7230 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7230; }
    { const char * tb_v7231 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7231; }
    { const char * tb_v7232 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7232; }
    { const char * tb_v7233 = "    long long rx[16], ry[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v7233; }
    { const char * tb_v7234 = "    for (int i = 0; i < n; i++) { rx[i] = tb_rnd(ax[i]); ry[i] = tb_rnd(ay[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7234; }
    { const char * tb_v7235 = "    for (int i = 1; i + 1 < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7235; }
    { const char * tb_v7236 = "        long long t[6] = { rx[0], ry[0], rx[i], ry[i], rx[i + 1], ry[i + 1] };\n"; *(const char * *)tb_grow(v_lines) = tb_v7236; }
    { const char * tb_v7237 = "        tb_tri_draw_i(t, c, pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7237; }
    { const char * tb_v7238 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7238; }
    { const char * tb_v7239 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7239; }
    { const char * tb_v7240 = "TB_API void tb_draw_triangle(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7240; }
    { const char * tb_v7241 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7241; }
    { const char * tb_v7242 = "    long long t[6] = { x1, y1, x2, y2, x3, y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7242; }
    { const char * tb_v7243 = "    int big = 0;   // (не far/near: на Windows это пустые слова из windows.h)\n"; *(const char * *)tb_grow(v_lines) = tb_v7243; }
    { const char * tb_v7244 = "    for (int i = 0; i < 6; i++) if (t[i] < -8192 || t[i] > 8192) big = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7244; }
    { const char * tb_v7245 = "    if (!big) { tb_tri_draw_i(t, c, 0); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7245; }
    { const char * tb_v7246 = "    double px[3] = { (double)x1, (double)x2, (double)x3 }, py[3] = { (double)y1, (double)y2, (double)y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7246; }
    { const char * tb_v7247 = "    tb_poly_draw(px, py, 3, c, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7247; }
    { const char * tb_v7248 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7248; }
    { const char * tb_v7249 = "// картинка из load_image: левый верхний угол в (x, y); прозрачные точки (меньше 128) не рисуются\n"; *(const char * *)tb_grow(v_lines) = tb_v7249; }
    { const char * tb_v7250 = "TB_API void tb_draw_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7250; }
    { const char * tb_v7251 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7251; }
    { const char * tb_v7252 = "    if (tb_gpu_on) tb_gpu_image(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v7252; }
    { const char * tb_v7253 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7253; }
    { const char * tb_v7254 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v7254; }
    { const char * tb_v7255 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v7255; }
    { const char * tb_v7256 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7256; }
    { const char * tb_v7257 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v7257; }
    { const char * tb_v7258 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7258; }
    { const char * tb_v7259 = "            uint32_t v = src[j * im->w + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7259; }
    { const char * tb_v7260 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v7260; }
    { const char * tb_v7261 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7261; }
    { const char * tb_v7262 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7262; }
    { const char * tb_v7263 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7263; }
    { const char * tb_v7264 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v7264; }
    { const char * tb_v7265 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v7265; }
    { const char * tb_v7266 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7266; }
    { const char * tb_v7267 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7267; }
    { const char * tb_v7268 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v7268; }
    { const char * tb_v7269 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7269; }
    { const char * tb_v7270 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v7270; }
    { const char * tb_v7271 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v7271; }
    { const char * tb_v7272 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7272; }
    { const char * tb_v7273 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v7273; }
    { const char * tb_v7274 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7274; }
    { const char * tb_v7275 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v7275; }
    { const char * tb_v7276 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7276; }
    { const char * tb_v7277 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7277; }
    { const char * tb_v7278 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7278; }
    { const char * tb_v7279 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7279; }
    { const char * tb_v7280 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7280; }
    { const char * tb_v7281 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7281; }
    { const char * tb_v7282 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7282; }
    { const char * tb_v7283 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7283; }
    { const char * tb_v7284 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7284; }
    { const char * tb_v7285 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v7285; }
    { const char * tb_v7286 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7286; }
    { const char * tb_v7287 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7287; }
    { const char * tb_v7288 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7288; }
    { const char * tb_v7289 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v7289; }
    { const char * tb_v7290 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7290; }
    { const char * tb_v7291 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7291; }
    { const char * tb_v7292 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7292; }
    { const char * tb_v7293 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7293; }
    { const char * tb_v7294 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v7294; }
    { const char * tb_v7295 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7295; }
    { const char * tb_v7296 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7296; }
    { const char * tb_v7297 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v7297; }
    { const char * tb_v7298 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7298; }
    { const char * tb_v7299 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v7299; }
    { const char * tb_v7300 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v7300; }
    { const char * tb_v7301 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7301; }
    { const char * tb_v7302 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v7302; }
    { const char * tb_v7303 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v7303; }
    { const char * tb_v7304 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v7304; }
    { const char * tb_v7305 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7305; }
    { const char * tb_v7306 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7306; }
    { const char * tb_v7307 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v7307; }
    { const char * tb_v7308 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v7308; }
    { const char * tb_v7309 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v7309; }
    { const char * tb_v7310 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v7310; }
    { const char * tb_v7311 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v7311; }
    { const char * tb_v7312 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v7312; }
    { const char * tb_v7313 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v7313; }
    { const char * tb_v7314 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7314; }
    { const char * tb_v7315 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v7315; }
    { const char * tb_v7316 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7316; }
    { const char * tb_v7317 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7317; }
    { const char * tb_v7318 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7318; }
    { const char * tb_v7319 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v7319; }
    { const char * tb_v7320 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7320; }
    { const char * tb_v7321 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7321; }
    { const char * tb_v7322 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7322; }
    { const char * tb_v7323 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v7323; }
    { const char * tb_v7324 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v7324; }
    { const char * tb_v7325 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v7325; }
    { const char * tb_v7326 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v7326; }
    { const char * tb_v7327 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v7327; }
    { const char * tb_v7328 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v7328; }
    { const char * tb_v7329 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v7329; }
    { const char * tb_v7330 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v7330; }
    { const char * tb_v7331 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v7331; }
    { const char * tb_v7332 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v7332; }
    { const char * tb_v7333 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v7333; }
    { const char * tb_v7334 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v7334; }
    { const char * tb_v7335 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v7335; }
    { const char * tb_v7336 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v7336; }
    { const char * tb_v7337 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v7337; }
    { const char * tb_v7338 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7338; }
    { const char * tb_v7339 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7339; }
    { const char * tb_v7340 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v7340; }
    { const char * tb_v7341 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v7341; }
    { const char * tb_v7342 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7342; }
    { const char * tb_v7343 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7343; }
    { const char * tb_v7344 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7344; }
    { const char * tb_v7345 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7345; }
    { const char * tb_v7346 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7346; }
    { const char * tb_v7347 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v7347; }
    { const char * tb_v7348 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7348; }
    { const char * tb_v7349 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7349; }
    { const char * tb_v7350 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7350; }
    { const char * tb_v7351 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7351; }
    { const char * tb_v7352 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7352; }
    { const char * tb_v7353 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7353; }
    { const char * tb_v7354 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7354; }
    { const char * tb_v7355 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7355; }
    { const char * tb_v7356 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7356; }
    { const char * tb_v7357 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v7357; }
    { const char * tb_v7358 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7358; }
    { const char * tb_v7359 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v7359; }
    { const char * tb_v7360 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7360; }
    { const char * tb_v7361 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v7361; }
    { const char * tb_v7362 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7362; }
    { const char * tb_v7363 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7363; }
    { const char * tb_v7364 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7364; }
    { const char * tb_v7365 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7365; }
    { const char * tb_v7366 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7366; }
    { const char * tb_v7367 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7367; }
    { const char * tb_v7368 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7368; }
    { const char * tb_v7369 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7369; }
    { const char * tb_v7370 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7370; }
    { const char * tb_v7371 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7371; }
    { const char * tb_v7372 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7372; }
    { const char * tb_v7373 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v7373; }
    { const char * tb_v7374 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7374; }
    { const char * tb_v7375 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7375; }
    { const char * tb_v7376 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7376; }
    { const char * tb_v7377 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7377; }
    { const char * tb_v7378 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7378; }
    { const char * tb_v7379 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7379; }
    { const char * tb_v7380 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7380; }
    { const char * tb_v7381 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7381; }
    { const char * tb_v7382 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7382; }
    { const char * tb_v7383 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7383; }
    { const char * tb_v7384 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7384; }
    { const char * tb_v7385 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v7385; }
    { const char * tb_v7386 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v7386; }
    { const char * tb_v7387 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7387; }
    { const char * tb_v7388 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7388; }
    { const char * tb_v7389 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v7389; }
    { const char * tb_v7390 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7390; }
    { const char * tb_v7391 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7391; }
    { const char * tb_v7392 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v7392; }
    { const char * tb_v7393 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7393; }
    { const char * tb_v7394 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7394; }
    { const char * tb_v7395 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v7395; }
    { const char * tb_v7396 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v7396; }
    { const char * tb_v7397 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7397; }
