    { const char * tb_v7424 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7424; }
    { const char * tb_v7425 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v7425; }
    { const char * tb_v7426 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7426; }
    { const char * tb_v7427 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7427; }
    { const char * tb_v7428 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v7428; }
    { const char * tb_v7429 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v7429; }
    { const char * tb_v7430 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v7430; }
    { const char * tb_v7431 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v7431; }
    { const char * tb_v7432 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v7432; }
    { const char * tb_v7433 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7433; }
