    { const char * tb_v7456 = "    double a = turn * 3.14159265358979323846 / 180, ca = cos(a), sa = sin(a);\n"; *(const char * *)tb_grow(v_lines) = tb_v7456; }
    { const char * tb_v7457 = "    double f = tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180), zn = 205.0 / 4096, hw = tb_gw / 2.0, hh = tb_gh / 2.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7457; }
    { const char * tb_v7458 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;   // та же рамка, что в tb_poly_draw\n"; *(const char * *)tb_grow(v_lines) = tb_v7458; }
    { const char * tb_v7459 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7459; }
