    { const char * tb_v7468 = "        double wx = p[0] * ca + p[2] * sa + x - tb_cam[0], wy = p[1] + y - tb_cam[1], wz = -p[0] * sa + p[2] * ca + z - tb_cam[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7468; }
    { const char * tb_v7469 = "        v->cx = wx * tb_cam[3] + wy * tb_cam[4] + wz * tb_cam[5];\n"; *(const char * *)tb_grow(v_lines) = tb_v7469; }
    { const char * tb_v7470 = "        v->cy = wx * tb_cam[6] + wy * tb_cam[7] + wz * tb_cam[8];\n"; *(const char * *)tb_grow(v_lines) = tb_v7470; }
    { const char * tb_v7471 = "        v->cz = wx * tb_camf[0] + wy * tb_camf[1] + wz * tb_camf[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7471; }
    { const char * tb_v7472 = "        v->front = v->cz >= zn;\n"; *(const char * *)tb_grow(v_lines) = tb_v7472; }
    { const char * tb_v7473 = "        v->near_ok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7473; }
    { const char * tb_v7474 = "        if (v->front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7474; }
