    { const char * tb_v7478 = "            v->dd = (1 - zn * iz) * 16777216.0;   // D = (1 - zn / z) * 2^24 — по экрану меняется ровно по плоскости\n"; *(const char * *)tb_grow(v_lines) = tb_v7478; }
