    { const char * tb_v7490 = "            if (!tb_tri3_plane(sx, sy, dd, pl)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7490; }
    { const char * tb_v7491 = "            if (v0->near_ok && v1->near_ok && v2->near_ok) {   // обычный случай: целиком в рамке\n"; *(const char * *)tb_grow(v_lines) = tb_v7491; }
    { const char * tb_v7492 = "                long long q[6] = { v0->rx, v0->ry, v1->rx, v1->ry, v2->rx, v2->ry };\n"; *(const char * *)tb_grow(v_lines) = tb_v7492; }
    { const char * tb_v7493 = "                tb_tri_draw_i(q, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7493; }
    { const char * tb_v7494 = "            } else tb_poly_draw(sx, sy, 3, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7494; }
    { const char * tb_v7495 = "            continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7495; }
    { const char * tb_v7496 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7496; }
    { const char * tb_v7497 = "        // часть треугольника за камерой: обрезаем всё ближе zn — выходит 0, 3 или 4 угла\n"; *(const char * *)tb_grow(v_lines) = tb_v7497; }
    { const char * tb_v7498 = "        tb_3v *vs[3] = { v0, v1, v2 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7498; }
