    { const char * tb_v7503 = "            if (p->front) { qx[n] = p->cx; qy[n] = p->cy; qz[n] = p->cz; n++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7503; }
    { const char * tb_v7504 = "            if (p->front != q->front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7504; }
