    { const char * tb_v7527 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v7527; }
    { const char * tb_v7528 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7528; }
    { const char * tb_v7529 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v7529; }
    { const char * tb_v7530 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7530; }
    { const char * tb_v7531 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7531; }
    { const char * tb_v7532 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7532; }
    { const char * tb_v7533 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7533; }
    { const char * tb_v7534 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7534; }
    { const char * tb_v7535 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7535; }
    { const char * tb_v7536 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7536; }
    { const char * tb_v7537 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7537; }
    { const char * tb_v7538 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v7538; }
    { const char * tb_v7539 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v7539; }
    { const char * tb_v7540 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7540; }
    { const char * tb_v7541 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7541; }
    { const char * tb_v7542 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7542; }
    { const char * tb_v7543 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7543; }
    { const char * tb_v7544 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7544; }
    { const char * tb_v7545 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v7545; }
    { const char * tb_v7546 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7546; }
    { const char * tb_v7547 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v7547; }
    { const char * tb_v7548 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7548; }
    { const char * tb_v7549 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7549; }
    { const char * tb_v7550 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7550; }
    { const char * tb_v7551 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v7551; }
    { const char * tb_v7552 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v7552; }
    { const char * tb_v7553 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v7553; }
    { const char * tb_v7554 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7554; }
    { const char * tb_v7555 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7555; }
    { const char * tb_v7556 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v7556; }
    { const char * tb_v7557 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7557; }
    { const char * tb_v7558 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7558; }
    { const char * tb_v7559 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7559; }
    { const char * tb_v7560 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7560; }
    { const char * tb_v7561 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7561; }
    { const char * tb_v7562 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v7562; }
    { const char * tb_v7563 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7563; }
    { const char * tb_v7564 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7564; }
    { const char * tb_v7565 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7565; }
    { const char * tb_v7566 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7566; }
    { const char * tb_v7567 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7567; }
    { const char * tb_v7568 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7568; }
    { const char * tb_v7569 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7569; }
    { const char * tb_v7570 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7570; }
    { const char * tb_v7571 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7571; }
    { const char * tb_v7572 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7572; }
    { const char * tb_v7573 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v7573; }
    { const char * tb_v7574 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v7574; }
    { const char * tb_v7575 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7575; }
    { const char * tb_v7576 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7576; }
    { const char * tb_v7577 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v7577; }
    { const char * tb_v7578 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7578; }
    { const char * tb_v7579 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7579; }
    { const char * tb_v7580 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7580; }
    { const char * tb_v7581 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники (номера углов, цвет)\n"; *(const char * *)tb_grow(v_lines) = tb_v7581; }
    { const char * tb_v7582 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7582; }
    { const char * tb_v7583 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7583; }
    { const char * tb_v7584 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7584; }
    { const char * tb_v7585 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7585; }
    { const char * tb_v7586 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v7586; }
    { const char * tb_v7587 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7587; }
    { const char * tb_v7588 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7588; }
    { const char * tb_v7589 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7589; }
