    { const char * tb_v7816 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7816; }
    { const char * tb_v7817 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7817; }
    { const char * tb_v7818 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v7818; }
    { const char * tb_v7819 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v7819; }
    { const char * tb_v7820 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v7820; }
    { const char * tb_v7821 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v7821; }
    { const char * tb_v7822 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7822; }
    { const char * tb_v7823 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v7823; }
    { const char * tb_v7824 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v7824; }
    { const char * tb_v7825 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v7825; }
    { const char * tb_v7826 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v7826; }
    { const char * tb_v7827 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v7827; }
    { const char * tb_v7828 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v7828; }
    { const char * tb_v7829 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v7829; }
    { const char * tb_v7830 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v7830; }
    { const char * tb_v7831 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v7831; }
    { const char * tb_v7832 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v7832; }
    { const char * tb_v7833 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7833; }
    { const char * tb_v7834 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7834; }
    { const char * tb_v7835 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v7835; }
    { const char * tb_v7836 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v7836; }
    { const char * tb_v7837 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v7837; }
    { const char * tb_v7838 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7838; }
    { const char * tb_v7839 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v7839; }
    { const char * tb_v7840 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7840; }
    { const char * tb_v7841 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7841; }
    { const char * tb_v7842 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v7842; }
    { const char * tb_v7843 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7843; }
    { const char * tb_v7844 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v7844; }
    { const char * tb_v7845 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v7845; }
    { const char * tb_v7846 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7846; }
    { const char * tb_v7847 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v7847; }
    { const char * tb_v7848 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v7848; }
    { const char * tb_v7849 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v7849; }
    { const char * tb_v7850 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7850; }
    { const char * tb_v7851 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7851; }
    { const char * tb_v7852 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7852; }
    { const char * tb_v7853 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v7853; }
    { const char * tb_v7854 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7854; }
    { const char * tb_v7855 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7855; }
    { const char * tb_v7856 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7856; }
    { const char * tb_v7857 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7857; }
    { const char * tb_v7858 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7858; }
    { const char * tb_v7859 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7859; }
    { const char * tb_v7860 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7860; }
    { const char * tb_v7861 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v7861; }
    { const char * tb_v7862 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7862; }
    { const char * tb_v7863 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v7863; }
    { const char * tb_v7864 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7864; }
    { const char * tb_v7865 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v7865; }
    { const char * tb_v7866 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v7866; }
    { const char * tb_v7867 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7867; }
    { const char * tb_v7868 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7868; }
    { const char * tb_v7869 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7869; }
    { const char * tb_v7870 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7870; }
    { const char * tb_v7871 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7871; }
    { const char * tb_v7872 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7872; }
    { const char * tb_v7873 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v7873; }
    { const char * tb_v7874 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7874; }
    { const char * tb_v7875 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7875; }
    { const char * tb_v7876 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v7876; }
    { const char * tb_v7877 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7877; }
    { const char * tb_v7878 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7878; }
    { const char * tb_v7879 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v7879; }
    { const char * tb_v7880 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7880; }
    { const char * tb_v7881 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7881; }
    { const char * tb_v7882 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v7882; }
    { const char * tb_v7883 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7883; }
    { const char * tb_v7884 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7884; }
    { const char * tb_v7885 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v7885; }
    { const char * tb_v7886 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7886; }
    { const char * tb_v7887 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7887; }
    { const char * tb_v7888 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7888; }
    { const char * tb_v7889 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7889; }
    { const char * tb_v7890 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7890; }
    { const char * tb_v7891 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v7891; }
    { const char * tb_v7892 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v7892; }
    { const char * tb_v7893 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v7893; }
    { const char * tb_v7894 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7894; }
    { const char * tb_v7895 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7895; }
    { const char * tb_v7896 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v7896; }
    { const char * tb_v7897 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7897; }
    { const char * tb_v7898 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7898; }
    { const char * tb_v7899 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7899; }
    { const char * tb_v7900 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7900; }
    { const char * tb_v7901 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v7901; }
    { const char * tb_v7902 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7902; }
    { const char * tb_v7903 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7903; }
    { const char * tb_v7904 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7904; }
    { const char * tb_v7905 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v7905; }
    { const char * tb_v7906 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7906; }
    { const char * tb_v7907 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7907; }
    { const char * tb_v7908 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v7908; }
    { const char * tb_v7909 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v7909; }
    { const char * tb_v7910 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v7910; }
    { const char * tb_v7911 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7911; }
    { const char * tb_v7912 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7912; }
    { const char * tb_v7913 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7913; }
    { const char * tb_v7914 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7914; }
    { const char * tb_v7915 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7915; }
    { const char * tb_v7916 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v7916; }
